// ── BUILD ALL ENTITIES ──
const allEntities = [];

function addEntities(arr, classification, dtiMin, dtiMax) {
  for (const e of arr) {
    allEntities.push({
      type: "synthetic_life",
      name: e.name,
      aliases: e.aliases || [],
      classification: e.classification || classification,
      disposition: e.disposition,
      habitat: e.habitat,
      origin: e.origin,
      status: "active",
      description: e.description,
      observed_behavior: e.observed_behavior,
      encounter_frequency: e.encounter_frequency,
      confirmed_sightings: e.confirmed_sightings,
      location: e.location,
      dti_rating: e.dti_rating != null ? e.dti_rating : randFloat(dtiMin, dtiMax),
      story_hooks: e.story_hooks,
      paratechnological: e.paratechnological
    });
  }
}

addEntities(superminds, "Supermind", 4, 7);
addEntities(leviathans, "Leviathan", 7, 10);
addEntities(prowlers, "Prowler", 3, 6);
addEntities(strays, "Stray", 1, 3);
addEntities(androids, "Android (Synthetic Person)", 0.1, 1.5);
addEntities(sentientRobots, "Sentient Robot", 0.1, 1.5);
addEntities(digitalPersons, "Digital Person", 0.1, 1.5);
addEntities(hybridIntelligences, "Hybrid Intelligence", 0.1, 1.5);
addEntities(uploadedConsciousnesses, "Uploaded Consciousness", 0.1, 1.5);

// ── WRITE FILES ──
let written = 0;
let skipped = 0;

for (const entity of allEntities) {
  const filename = slug(entity.name) + '.json';
  if (existing.has(filename)) {
    console.log(`SKIP (exists): ${filename}`);
    skipped++;
    continue;
  }
  const filePath = path.join(OUTPUT_DIR, filename);
  fs.writeFileSync(filePath, JSON.stringify(entity, null, 2), 'utf8');
  console.log(`WROTE: ${filename}`);
  written++;
}

console.log(`\nDone. Written: ${written}, Skipped: ${skipped}, Total entities: ${allEntities.length}`);
